detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total weight (or total units) of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped (i.e., every unit of A, B, C, D, E must be packed into containers), or is it acceptable to leave some goods unshipped as long as the containers that are used satisfy the rules?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether all goods must be shipped or if some can be left unshipped."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers fixed in advance (a given fleet size we must work within), or is it a decision variable we choose, with the objective being to minimize how many we use?"
  ],
  "rationale": "The response asks for a single policy choice regarding the status of the container count (fixed parameter vs. decision variable), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The \"at least 12 units of type D per container\" rule — does it apply to every container that is used, or only to containers that actually contain some type D goods?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy scope definition."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule \"if a container contains any type A then it must also contain at least one type C\" — does this apply to every container that is used (i.e., any used container with A≥1 must have C≥1), or only to containers that contain A?"
  ],
  "rationale": "The response asks a single clarification question regarding the scope of a specific rule, presenting two mutually exclusive interpretations for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (each unit must be assigned whole to a single container, so all counts are integers), or can units be split fractionally across containers?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The 18-ton minimum and 60-ton maximum per container — are these strict weight bounds that must hold for every used container (i.e., 18 ≤ weight ≤ 60), or is the 18-ton figure a soft target that may be relaxed if needed?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the nature of the weight constraints (strict bounds vs. soft target), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "is it acceptable for the plan to leave some goods unshipped (i.e., not every available unit must be packed), or must all available goods be shipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice between allowing unshipped goods or requiring all goods to be shipped."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
